     1|/**
     2| * IVX Reels — full-screen vertical video feed matching ivxholding.com exactly.
     3| *
     4| * Same backend the landing page uses:
     5| *   feed      → GET /api/ivx/video-platform/feed
     6| *   like      → POST /api/projects/:id/like
     7| *   save      → POST /api/projects/:id/save
     8| *   share     → POST /api/projects/:id/share
     9| *   follow    → POST /api/ivx/video-platform/follow
    10| *   report    → POST /api/ivx/video-platform/videos/:id/report
    11| *   comments  → GET/POST /api/projects/:id/comments
    12| *
    13| * Player lifecycle (Instagram-style):
    14| *   • Only ONE reel plays at a time (the active/index item)
    15| *   • Max 3 players mounted (active ± 1) — all others unmounted
    16| *   • Pauses on app background, screen unfocus, network disconnect
    17| *   • 80% viewability threshold to prevent overlap during fast scroll
    18| *   • Per-item error boundary so one bad video never crashes the feed
    19| */
    20|import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
    21|import {
    22|  View,
    23|  Text,
    24|  StyleSheet,
    25|  FlatList,
    26|  TouchableOpacity,
    27|  ActivityIndicator,
    28|  useWindowDimensions,
    29|  Platform,
    30|  Alert,
    31|} from 'react-native';
    32|import { Stack, useRouter, useLocalSearchParams } from 'expo-router';
    33|import { useSafeAreaInsets } from 'react-native-safe-area-context';
    34|import { X } from 'lucide-react-native';
    35|import { RefreshControl } from 'react-native';
    36|import * as Haptics from 'expo-haptics';
    37|import { useQuery } from '@tanstack/react-query';
    38|
    39|import Colors from '@/constants/colors';
    40|import { fetchVideoFeed, type FeedVideo } from '@/lib/video-feed';
    41|import {
    42|  toggleVideoFollow,
    43|  reportVideo,
    44|  getViewerId,
    45|  buildVideoShareUrl,
    46|} from '@/lib/video-platform';
    47|import ProjectCommentsSheet from '@/components/ProjectCommentsSheet';
    48|import ProjectShareSheet from '@/components/ProjectShareSheet';
    49|import CanonicalInvestmentReelCard, {
    50|  feedVideoToReelData,
    51|  type CanonicalReelData,
    52|} from '@/components/CanonicalInvestmentReelCard';
    53|import { useReelPlayback } from '@/hooks/useReelPlayback';
    54|import { useReelEngagement, type EngagementState } from '@/hooks/useReelEngagement';
    55|import { ModuleErrorBoundary } from '@/components/ModuleErrorBoundary';
    56|import {
    57|  fetchProjectComments,
    58|  addProjectComment,
    59|  deleteProjectComment,
    60|  type ProjectComment,
    61|} from '@/lib/project-engagement';
    62|import { supabase } from '@/lib/supabase';
    63|
    64|const GOLD = Colors.primary;
    65|
    66|type ReelChannel = 'all' | 'investment' | 'buyer' | 'seller';
    67|
    68|const CHANNELS: { id: ReelChannel; label: string }[] = [
    69|  { id: 'all', label: 'All' },
    70|  { id: 'investment', label: 'Investments' },
    71|  { id: 'buyer', label: 'Buyers' },
    72|  { id: 'seller', label: 'Sellers' },
    73|];
    74|
    75|export default function VideosScreen() {
    76|  const router = useRouter();
    77|  const insets = useSafeAreaInsets();
    78|  const { height: windowHeight } = useWindowDimensions();
    79|  const params = useLocalSearchParams<{ type?: string }>();
    80|  void params;
    81|  const [muted, setMuted] = useState<boolean>(true);
    82|  const [userId, setUserId] = useState<string | null>(null);
    83|  const [viewerId, setViewerId] = useState<string | null>(null);
    84|  const [channel, setChannel] = useState<ReelChannel>('all');
    85|
    86|  const [commentsVideo, setCommentsVideo] = useState<FeedVideo | null>(null);
    87|  const [comments, setComments] = useState<ProjectComment[]>([]);
    88|  const [commentsTotal, setCommentsTotal] = useState<number>(0);
    89|  const [commentsLoading, setCommentsLoading] = useState<boolean>(false);
    90|  const [shareVideo, setShareVideo] = useState<FeedVideo | null>(null);
    91|  const [toast, setToast] = useState<string | null>(null);
    92|
    93|  // Progressive loading: fetch first page of 10, then load more on scroll
    94|  const [allVideos, setAllVideos] = useState<FeedVideo[]>([]);
    95|  const [hasMore, setHasMore] = useState<boolean>(true);
    96|  const [isFetchingMore, setIsFetchingMore] = useState<boolean>(false);
    97|  const loadedIds = useRef<Set<string>>(new Set());
    98|  const offsetRef = useRef<number>(0);
    99|  const PAGE_SIZE = 10;
   100|
   101|  const feedQuery = useQuery({
   102|    queryKey: ['ivx-video-feed'],
   103|    queryFn: () => {
   104|      offsetRef.current = 0;
   105|      return fetchVideoFeed(PAGE_SIZE, 0);
   106|    },
   107|    staleTime: 60_000,
   108|    retry: 2,
   109|  });
   110|
   111|  // Sync initial query results into local state via guarded effect
   112|  const queryData = feedQuery.data;
   113|  useEffect(() => {
   114|    if (!queryData || queryData.length === 0 || feedQuery.isLoading) return;
   115|    const seen = new Set<string>();
   116|    const deduped = queryData.filter((v) => {
   117|      if (seen.has(v.id)) return false;
   118|      seen.add(v.id);
   119|      return true;
   120|    });
   121|    loadedIds.current = new Set(deduped.map((v) => v.id));
   122|    offsetRef.current = deduped.length;
   123|    setHasMore(deduped.length >= PAGE_SIZE);
   124|    setAllVideos(deduped);
   125|  }, [queryData, feedQuery.isLoading]);
   126|
   127|  const loadMore = useCallback(() => {
   128|    if (isFetchingMore || !hasMore || feedQuery.isLoading) return;
   129|    setIsFetchingMore(true);
   130|    const currentOffset = offsetRef.current;
   131|    void fetchVideoFeed(PAGE_SIZE, currentOffset)
   132|      .then((more) => {
   133|        const newItems = more.filter((v) => !loadedIds.current.has(v.id));
   134|        if (newItems.length === 0) {
   135|          setHasMore(false);
   136|        } else {
   137|          for (const v of newItems) loadedIds.current.add(v.id);
   138|          offsetRef.current = currentOffset + newItems.length;
   139|          setAllVideos((prev) => {
   140|            // Deduplicate by ID in the combined array
   141|            const combined = [...prev];
   142|            for (const v of newItems) {
   143|              if (!combined.some((existing) => existing.id === v.id)) {
   144|                combined.push(v);
   145|              }
   146|            }
   147|            return combined;
   148|          });
   149|        }
   150|      })
   151|      .catch(() => setHasMore(false))
   152|      .finally(() => setIsFetchingMore(false));
   153|  }, [isFetchingMore, hasMore, feedQuery.isLoading]);
   154|
   155|  const filteredVideos = useMemo(() => {
   156|    if (channel === 'all') return allVideos;
   157|    if (channel === 'investment') return allVideos.filter(v => v.deal && v.video_type !== 'reel');
   158|    if (channel === 'buyer') {
   159|      return allVideos.filter(
   160|        v =>
   161|          (v.deal?.deal_type ?? '').toLowerCase().includes('buy') ||
   162|          v.title?.toLowerCase().includes('buy') ||
   163|          v.title?.toLowerCase().includes('buyer')
   164|      );
   165|    }
   166|    if (channel === 'seller') {
   167|      return allVideos.filter(
   168|        v =>
   169|          (v.deal?.deal_type ?? '').toLowerCase().includes('sell') ||
   170|          v.title?.toLowerCase().includes('sell') ||
   171|          v.title?.toLowerCase().includes('seller')
   172|      );
   173|    }
   174|    return allVideos;
   175|  }, [allVideos, channel]);
   176|
   177|  const counts = useMemo(() => {
   178|    const all = allVideos.length;
   179|    const investment = allVideos.filter(v => v.deal && v.video_type !== 'reel').length;
   180|    const buyer = allVideos.filter(
   181|      v =>
   182|        (v.deal?.deal_type ?? '').toLowerCase().includes('buy') ||
   183|        v.title?.toLowerCase().includes('buy') ||
   184|        v.title?.toLowerCase().includes('buyer')
   185|    ).length;
   186|    const seller = allVideos.filter(
   187|      v =>
   188|        (v.deal?.deal_type ?? '').toLowerCase().includes('sell') ||
   189|        v.title?.toLowerCase().includes('sell') ||
   190|        v.title?.toLowerCase().includes('seller')
   191|    ).length;
   192|    return { all, investment, buyer, seller };
   193|  }, [allVideos]);
   194|
   195|  // Playback lifecycle hooks
   196|  const playback = useReelPlayback();
   197|  const engagement = useReelEngagement();
   198|  // Destructure stable callbacks to avoid effect dependency loops
   199|  const { initEngagements, handleView } = engagement;
   200|
   201|  useEffect(() => {
   202|    let cancelled = false;
   203|    void getViewerId().then((id) => {
   204|      if (!cancelled) setViewerId(id);
   205|    });
   206|    void supabase.auth.getSession().then(({ data }) => {
   207|      if (!cancelled && data.session?.user?.id) setUserId(data.session.user.id);
   208|    }).catch(() => {});
   209|    return () => { cancelled = true; };
   210|  }, []);
   211|
   212|  // Initialize engagement state when videos load
   213|  // Use allVideos.length as dependency, not the engagement object itself
   214|  useEffect(() => {
   215|    if (allVideos.length === 0) return;
   216|    initEngagements(allVideos);
   217|  }, [allVideos, initEngagements]);
   218|
   219|  // Track view events when active reel changes
   220|  // Use playback.activeIndex and filteredVideos as deps, not engagement
   221|  useEffect(() => {
   222|    const activeVideo = filteredVideos[playback.activeIndex];
   223|    if (!activeVideo) return;
   224|    handleView(activeVideo);
   225|  }, [playback.activeIndex, filteredVideos, handleView]);
   226|
   227|  const showToast = useCallback((message: string) => {
   228|    setToast(message);
   229|    setTimeout(() => setToast(null), 2500);
   230|  }, []);
   231|
   232|  const handleLike = useCallback((video: FeedVideo) => {
   233|    engagement.handleLike(video, userId);
   234|  }, [engagement, userId]);
   235|
   236|  const handleDoubleTapLike = useCallback((video: FeedVideo) => {
   237|    engagement.handleDoubleTapLike(video, userId);
   238|  }, [engagement, userId]);
   239|
   240|  const handleComment = useCallback(async (video: FeedVideo) => {
   241|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
   242|    setCommentsLoading(true);
   243|    setCommentsVideo(video);
   244|    try {
   245|      const { comments: cmts, total } = await fetchProjectComments(video.id, 20, 0);
   246|      setComments(cmts);
   247|      setCommentsTotal(total);
   248|    } catch {} finally {
   249|      setCommentsLoading(false);
   250|    }
   251|  }, []);
   252|
   253|  const handleAddComment = useCallback(async (projectId: string, body: string, parentId?: string) => {
   254|    try {
   255|      await addProjectComment(projectId, body, userId, undefined, parentId);
   256|      const { comments: cmts, total } = await fetchProjectComments(projectId, 20, 0);
   257|      setComments(cmts);
   258|      setCommentsTotal(total);
   259|    } catch {}
   260|  }, [userId]);
   261|
   262|  const handleDeleteComment = useCallback(async (commentId: string) => {
   263|    if (!commentsVideo) return;
   264|    try {
   265|      await deleteProjectComment(commentId);
   266|      const { comments: cmts, total } = await fetchProjectComments(commentsVideo.id, 20, 0);
   267|      setComments(cmts);
   268|      setCommentsTotal(total);
   269|    } catch {}
   270|  }, [commentsVideo]);
   271|
   272|  const handleShare = useCallback((video: FeedVideo) => {
   273|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
   274|    setShareVideo(video);
   275|  }, []);
   276|
   277|  const handleShareTrack = useCallback(async (projectId: string, shareType: string) => {
   278|    engagement.handleShare(
   279|      { id: projectId } as FeedVideo,
   280|      userId,
   281|      shareType,
   282|    );
   283|  }, [engagement, userId]);
   284|
   285|  const handleSave = useCallback((video: FeedVideo) => {
   286|    engagement.handleSave(video, viewerId);
   287|  }, [engagement, viewerId]);
   288|
   289|  const handleFollow = useCallback(async (video: FeedVideo) => {
   290|    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
   291|    const creatorId = video.creator_id ?? 'ivx-owner';
   292|    try {
   293|      const result = await toggleVideoFollow(creatorId, viewerId);
   294|      showToast(result.following ? 'Following creator' : 'Unfollowed');
   295|    } catch {}
   296|  }, [viewerId, showToast]);
   297|
   298|  const handleReport = useCallback((video: FeedVideo) => {
   299|    if (Platform.OS === 'web') {
   300|      const reason = window.prompt('Report this video — reason:');
   301|      if (!reason) return;
   302|      void reportVideo(video.id, reason, viewerId).then(() => showToast('Report submitted to moderation')).catch(() => showToast('Report failed'));
   303|      return;
   304|    }
   305|    Alert.prompt('Report this video', 'Reason:', async (reason) => {
   306|      if (!reason) return;
   307|      try {
   308|        await reportVideo(video.id, reason, viewerId);
   309|        showToast('Report submitted to moderation');
   310|      } catch {
   311|        showToast('Report failed');
   312|      }
   313|    });
   314|  }, [viewerId, showToast]);
   315|
   316|  const handleViewDeal = useCallback((video: FeedVideo) => {
   317|    if (video.deal?.url) {
   318|      router.push(video.deal.url as any);
   319|    } else if (video.deal?.id) {
   320|      router.push({ pathname: '/jv-invest', params: { jvId: video.deal.id } } as any);
   321|    }
   322|  }, [router]);
   323|
   324|  const handleInvestNow = useCallback((video: FeedVideo) => {
   325|    if (video.deal?.id) {
   326|      router.push({ pathname: '/jv-invest', params: { jvId: video.deal.id } } as any);
   327|    }
   328|  }, [router]);
   329|
   330|  // Keep a ref to the latest engagements so getEngagement can read
   331|  // current state without being a dependency of renderItem (which
   332|  // would cause all FeedItems to re-render on every like/save).
   333|  const engagementsRef = useRef(engagement.engagements);
   334|  engagementsRef.current = engagement.engagements;
   335|
   336|  // Stable getter: reads from ref so the callback identity never changes.
   337|  // FeedItem receives the engagement value at render time; when a like
   338|  // updates the ref, only the affected FeedItem re-renders (via its own
   339|  // engagement prop diff), not the entire FlatList.
   340|  const getEngagement = useCallback(
   341|    (videoId: string, fallback: FeedVideo): EngagementState => {
   342|      return engagementsRef.current[videoId] ?? {
   343|        likeCount: fallback.like_count ?? 0,
   344|        commentCount: fallback.comment_count ?? 0,
   345|        shareCount: fallback.share_count ?? 0,
   346|        saveCount: fallback.save_count ?? 0,
   347|        liked: false,
   348|        saved: false,
   349|        following: false,
   350|      };
   351|    },
   352|    [],
   353|  );
   354|
   355|  const renderItem = useCallback(
   356|    ({ item, index }: { item: FeedVideo; index: number }) => {
   357|      const reelData = feedVideoToReelData(item);
   358|      const eng = getEngagement(item.id, item);
   359|      const mergedData: CanonicalReelData = {
   360|        ...reelData,
   361|        isLiked: eng.liked,
   362|        isSaved: eng.saved,
   363|        likeCount: eng.likeCount,
   364|        saveCount: eng.saveCount,
   365|        shareCount: eng.shareCount,
   366|        commentCount: eng.commentCount,
   367|      };
   368|      return (
   369|        <CanonicalInvestmentReelCard
   370|          data={mergedData}
   371|          mode="reel"
   372|          isActive={playback.shouldPlay(index)}
   373|          shouldMountVideo={playback.shouldMount(index, filteredVideos.length)}
   374|          isMuted={muted}
   375|          feedHeight={windowHeight}
   376|          onToggleMute={() => setMuted(m => !m)}
   377|          onLike={(d) => handleLike(item)}
   378|          onComment={(d) => handleComment(item)}
   379|          onSave={(d) => handleSave(item)}
   380|          onShare={(d) => handleShare(item)}
   381|          onOpenDeal={(d) => handleViewDeal(item)}
   382|          onInvest={(d) => handleInvestNow(item)}
   383|        />
   384|      );
   385|    },
   386|    [playback, filteredVideos.length, windowHeight, muted, getEngagement, handleLike, handleComment, handleShare, handleSave, handleViewDeal, handleInvestNow]
   387|  );
   388|
   389|  const itemHeight = windowHeight;
   390|
   391|  return (
   392|    <View style={styles.container}>
   393|      <Stack.Screen options={{ headerShown: false }} />
   394|
   395|      {/* Top filter chips — matches the owner-approved reels screenshot */}
   396|      <View style={[styles.topBar, { paddingTop: insets.top + 8 }]}>
   397|        <View style={styles.topRow}>
   398|          <View style={styles.tabs}>
   399|            {CHANNELS.map((ch) => (
   400|              <TouchableOpacity
   401|                key={ch.id}
   402|                style={[styles.tab, channel === ch.id && styles.tabActive]}
   403|                onPress={() => setChannel(ch.id)}
   404|                testID={`reels-channel-${ch.id}`}
   405|                activeOpacity={0.85}
   406|              >
   407|                <Text style={[styles.tabText, channel === ch.id && styles.tabTextActive]}>
   408|                  {ch.label} {counts[ch.id]}
   409|                </Text>
   410|              </TouchableOpacity>
   411|            ))}
   412|          </View>
   413|          <TouchableOpacity onPress={() => router.back()} style={styles.closeBtn} testID="reels-close">
   414|            <X size={22} color="#fff" />
   415|          </TouchableOpacity>
   416|        </View>
   417|      </View>
   418|
   419|      {feedQuery.isLoading ? (
   420|        <View style={styles.loading}>
   421|          <ActivityIndicator size="large" color={GOLD} />
   422|        </View>
   423|      ) : filteredVideos.length === 0 ? (
   424|        <View style={styles.loading}>
   425|          <Text style={styles.emptyText}>No videos available</Text>
   426|        </View>
   427|      ) : (
   428|        <ModuleErrorBoundary moduleName="Reels">
   429|        <FlatList
   430|          data={filteredVideos}
   431|          keyExtractor={(v) => v.id}
   432|          renderItem={renderItem}
   433|          pagingEnabled
   434|          decelerationRate="fast"
   435|          snapToInterval={itemHeight}
   436|          snapToAlignment="start"
   437|          showsVerticalScrollIndicator={false}
   438|          onViewableItemsChanged={playback.handleViewableItemsChanged}
   439|          viewabilityConfig={playback.viewabilityConfig}
   440|          initialNumToRender={2}
   441|          maxToRenderPerBatch={3}
   442|          windowSize={5}
   443|          removeClippedSubviews
   444|          getItemLayout={(_data, index) => ({ length: itemHeight, offset: itemHeight * index, index })}
   445|          onEndReached={loadMore}
   446|          onEndReachedThreshold={0.5}
   447|          ListFooterComponent={
   448|            isFetchingMore ? (
   449|              <View style={{ height: windowHeight, alignItems: 'center', justifyContent: 'center' }}>
   450|                <ActivityIndicator size="large" color={GOLD} />
   451|              </View>
   452|            ) : null
   453|          }
   454|          refreshControl={
   455|            <RefreshControl
   456|              refreshing={feedQuery.isRefetching}
   457|              onRefresh={() => {
   458|                loadedIds.current = new Set();
   459|                offsetRef.current = 0;
   460|                setHasMore(true);
   461|                void feedQuery.refetch();
   462|              }}
   463|              tintColor={GOLD}
   464|            />
   465|          }
   466|          contentContainerStyle={{ paddingTop: 0 }}
   467|        />
   468|        </ModuleErrorBoundary>
   469|      )}
   470|
   471|      {toast && (
   472|        <View style={styles.toast} pointerEvents="none">
   473|          <Text style={styles.toastText}>{toast}</Text>
   474|        </View>
   475|      )}
   476|
   477|      {commentsVideo && (
   478|        <ProjectCommentsSheet
   479|          visible={commentsVideo !== null}
   480|          projectId={commentsVideo.id}
   481|          comments={comments}
   482|          totalComments={commentsTotal}
   483|          isLoading={commentsLoading}
   484|          onClose={() => setCommentsVideo(null)}
   485|          onAddComment={handleAddComment}
   486|          onDeleteComment={handleDeleteComment}
   487|        />
   488|      )}
   489|
   490|      {shareVideo && (
   491|        <ProjectShareSheet
   492|          visible={shareVideo !== null}
   493|          projectId={shareVideo.id}
   494|          projectTitle={shareVideo.title ?? 'IVX Property'}
   495|          projectUrl={buildVideoShareUrl(shareVideo.id)}
   496|          onClose={() => setShareVideo(null)}
   497|          onShareTrack={handleShareTrack}
   498|        />
   499|      )}
   500|    </View>
   501|  );
   502|}
   503|
   504|const styles = StyleSheet.create({
   505|  container: {
   506|    flex: 1,
   507|    backgroundColor: '#000',
   508|  },
   509|  topBar: {
   510|    position: 'absolute',
   511|    top: 0,
   512|    left: 0,
   513|    right: 0,
   514|    zIndex: 30,
   515|    paddingHorizontal: 10,
   516|    paddingBottom: 10,
   517|  },
   518|  topRow: {
   519|    flexDirection: 'row',
   520|    alignItems: 'center',
   521|    justifyContent: 'space-between',
   522|    gap: 8,
   523|  },
   524|  closeBtn: {
   525|    width: 36,
   526|    height: 36,
   527|    borderRadius: 18,
   528|    backgroundColor: 'rgba(0,0,0,0.35)',
   529|    alignItems: 'center',
   530|    justifyContent: 'center',
   531|  },
   532|  tabs: {
   533|    flex: 1,
   534|    flexDirection: 'row',
   535|    gap: 6,
   536|    justifyContent: 'center',
   537|    alignItems: 'center',
   538|  },
   539|  tab: {
   540|    flexShrink: 0,
   541|    backgroundColor: 'rgba(255,255,255,0.18)',
   542|    borderRadius: 999,
   543|    paddingVertical: 7,
   544|    paddingHorizontal: 14,
   545|  },
   546|  tabActive: {
   547|    backgroundColor: GOLD,
   548|  },
   549|  tabText: {
   550|    color: '#fff',
   551|    fontSize: 13,
   552|    fontWeight: '700' as const,
   553|    textShadowColor: 'rgba(0,0,0,0.6)',
   554|    textShadowOffset: { width: 0, height: 1 },
   555|    textShadowRadius: 3,
   556|  },
   557|  tabTextActive: {
   558|    color: '#000',
   559|    textShadowColor: 'transparent',
   560|  },
   561|  loading: {
   562|    flex: 1,
   563|    alignItems: 'center',
   564|    justifyContent: 'center',
   565|  },
   566|  emptyText: {
   567|    color: 'rgba(255,255,255,0.5)',
   568|    fontSize: 15,
   569|  },
   570|  toast: {
